beforeExample:
import org.eclipse.jface.viewers.ISelection;
import org.eclipse.jface.text.ITextSelection;

public class MyClass {
    public void someMethod(ISelection selection) {
        if (selection instanceof ITextSelection && !selection.isEmpty()) {
            System.out.println("Text selected.");
        }
    }
}

afterExample:
import org.eclipse.jface.viewers.ISelection;
import org.eclipse.jface.text.ITextSelection;

public class MyClass {
    public void someMethod(ISelection selection) {
        if (selection instanceof org.eclipse.jface.text.ITextSelection && !selection.isEmpty() && ((org.eclipse.jface.text.ITextSelection)selection).getLength() > 0) {
            System.out.println("Text selected.");
        }
    }
}

negativeExample:
import org.eclipse.jface.viewers.ISelection;
import org.eclipse.jface.text.ITextSelection;
import org.eclipse.jface.viewers.IStructuredSelection;

public class MyClass {
    public void someOtherMethod(ISelection selection) {
        // Should not match if condition is different (different instanceof type)
        if (selection instanceof IStructuredSelection && !selection.isEmpty()) {
            System.out.println("Structured selection.");
        }

        // Should not match if already correct
        if (selection instanceof ITextSelection && !selection.isEmpty() && ((ITextSelection)selection).getLength() > 0) {
            System.out.println("Already correct.");
        }

        // Should not match if ITextSelection.isEmpty() is not combined with instanceof check in the same way
        if (selection instanceof ITextSelection && selection.isEmpty()) {
            System.out.println("Empty text selection specifically.");
        }
    }
}
